import{_ as i,l,o as e,c as s,v as o,p as d,x as t,d as n,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const R=JSON.parse('{"title":"RCWA","description":"","frontmatter":{"title":"RCWA","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/rcwa.md","filePath":"litho/rcwa.md","lastUpdated":1789023840000}'),A={name:"litho/rcwa.md"};function c(E,a,D,m,_,C){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="rcwa" tabindex="-1">RCWA <a class="header-anchor" href="#rcwa" aria-label="Permalink to &quot;RCWA&quot;">​</a></h1><div class="epigraph"><p>周期掩模是一层层傅里叶模态：RCWA 把麦克斯韦收成耦合波，线栅与接触阵列比体网格便宜。</p><footer>—— 对照 Moharam 与 Gaylord 的 rigorous coupled-wave analysis（RCWA / FMM）</footer></div><p><a href="/litho/fdtd-mask">上一课</a>用 FDTD 吃非周期 3D。缺口是 SRAM、密线、孔阵列在光学上近似周期，用体网格浪费。本课钉 RCWA。把大场拆成可算的块，留给[下一课](/litho/domain-decomposition-mask）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RCWA（也称傅里叶模态法）沿周期方向把场展成平面波/布洛赫模态，在分层膜堆里匹配边界，求衍射级振幅。天然适合 1D/2D 周期吸收体 + 多层。截断级次决定精度与矩阵大小：级次不够，高 NA 大角度的倏逝耦合会错；级次太多，全芯片仍不可能，但「一个节距的严格光谱」足够校准 3D 核、解释禁戒节距附近的 mask 3D。</p><p>缺口是<strong>周期严格解</strong>，不是再步进一次 Yee。把 RCWA 用于孤立缺陷，要靠超胞——缺陷密度被周期赝像污染，那是 FDTD 的活。</p><h3 id="与-ocd-计量同族" tabindex="-1">与 OCD 计量同族 <a class="header-anchor" href="#与-ocd-计量同族" aria-label="Permalink to &quot;与 OCD 计量同族&quot;">​</a></h3><p>晶圆 <a href="/litho/ocd-mueller">OCD</a> 也常用 RCWA 反演周期结构。掩模侧与晶圆侧是同一数学，光学常数与剖面不同。不要把计量课的穆勒矩阵在这里重推。</p><p><span class="marginnote">收敛要用李级数或适当的傅里叶因式分解（Li 规则一类），否则金属栅的吉布斯现象会假扮成 3D 效应。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入：节距、占空比、侧壁角、膜堆 \\(n,k\\)、入射角与偏振。输出：各衍射级复振幅，进入 Hopkins/Abbe 成像。SMO 评估候选节距时，用 RCWA 扫一维/二维周期比 FDTD 快一个数量级以上（视维度）。EUV 斜入射与方位角必须扫，不能只正入射。</p><p>校准：把 RCWA 光谱当老师，拟合紧凑 mask 3D 边界条件或有效薄屏。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分层结构里每层的麦克斯韦在傅里叶空间是耦合常微分方程（或特征值问题）。界面匹配给出散射矩阵。吸收体侧壁倾斜则用多层阶梯逼近——阶梯太粗，又回到剖面误差。偏振：TM 在金属/高对比栅上更难收敛，高 NA 浸没与 EUV 都不能当标量。</p>',14)),(e(),d(p,null,{default:t(()=>[h(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PER%5B%22%E5%91%A8%E6%9C%9F%E5%89%96%E9%9D%A2%20%2B%20%E8%86%9C%E5%A0%86%22%5D%20--%3E%20RCWA%5B%22%E8%80%A6%E5%90%88%E6%B3%A2%20%2F%20%E6%95%A3%E5%B0%84%E7%9F%A9%E9%98%B5%22%5D%0A%20%20RCWA%20--%3E%20ORD%5B%22%E8%A1%8D%E5%B0%84%E7%BA%A7%E6%8C%AF%E5%B9%85%22%5D%0A%20%20ORD%20--%3E%20IMG%5B%22%E9%83%A8%E5%88%86%E7%9B%B8%E5%B9%B2%E6%88%90%E5%83%8F%22%5D%0A%20%20ORD%20--%3E%20COMP%5B%22%E7%B4%A7%E5%87%91%203D%20%E6%A0%B8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>RCWA 不处理真正孤立的修复补丁（除非超胞且接受赝周期）。不算胶。傅里叶截断是精度旋钮，不是物理 NA。</p><p>后课默认：周期掩模电磁有模态法；下一课处理既非纯周期也非全 FDTD 的大场——域分解。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RCWA 用傅里叶模态解周期掩模 EMF，适合线栅/阵列校准。</li><li>孤立缺陷用 FDTD 或小心超胞；金属 TM 要检查傅里叶收敛。</li><li>输出是衍射级，供成像与紧凑 3D 当老师。</li><li>出处：Moharam &amp; Gaylord RCWA；傅里叶模态法在光刻掩模中的应用。</li></ul>',5))])}const f=i(A,[["render",c]]);export{R as __pageData,f as default};
